// Pseudocode: Signing Transaction via FIPS 140-2 HSM
async function signPayloadWithHSM(payloadHash, keyHandle) {
  const session = await hsm.openSession({ pin: process.env.HSM_PIN });
  try {
    const signature = await session.sign({
      mechanism: CKM_ECDSA_SHA256,
      key: keyHandle,
      data: payloadHash
    });
    return signature.toString('hex');
  } finally {
    await session.close();
  }
}

// Automated Threat Containment Webhook (SOAR)
app.post('/api/soar/containment-alert', async (req, res) => {
  const { hostIp, threatType, severity } = req.body;
  if (severity === 'CRITICAL' && threatType === 'RANSOMWARE_ENCRYPTION_DETECTED') {
    // 1. Isolate endpoint from network
    await edr.isolateHost(hostIp);
    // 2. Revoke active Active Directory tokens for compromised user
    await activeDirectory.revokeAllTokens(req.body.userPrincipal);
    // 3. Notify CISO and aeCERT incident desk
    await pagerDuty.triggerHighSeverityAlert({ hostIp, threatType });
    return res.json({ status: 'Host isolated, tokens revoked within 450ms' });
  }
});
